"engine/explain-plan.js": function(module, exports, require) {
'use strict';

const format = (value) => Number(value.toFixed(4)).toString();

// Pure presentation boundary: a future explanation provider must preserve the
// calculated fields. This implementation needs no model, key, clock or network.
function explainPlan(plan) {
  const topics = new Map(plan.topic_analysis.map((topic) => [topic.topic_id, topic]));
  const priorities = plan.priorities.map((task) => {
    const topic = topics.get(task.topic_id);
    let reason = `Review ${task.topic_name}: your observed assessment score is ${format(topic.observed_score)}%, ${format(topic.target_gap)} points below the ${format(plan.target_score)}% reference target. Configured importance ${format(topic.importance)} and estimate ${format(topic.estimated_minutes)} minutes give a priority score of ${format(topic.priority_score)}. Use ${task.resource_id} for ${task.duration_minutes} minutes.`;
    if (task.is_partial) reason += ` This is partial practice (${task.duration_minutes} of ${format(task.estimated_minutes)} configured minutes); work through as much of the activity as the allocated blocks allow.`;
    return { ...task, reason };
  });
  let summary;
  if (plan.status === 'no_scores') summary = 'No observed topic scores are available. Add topic-level assessment results before generating remedial tasks.';
  else if (plan.status === 'target_met') summary = `All available topic scores meet the ${format(plan.target_score)}% reference target. No remedial tasks were added.`;
  else if (plan.status === 'no_study_time') summary = 'The total time budget is 0 minutes. Score gaps were analysed, but no learning blocks can be scheduled.';
  else if (plan.status === 'insufficient_block_time') summary = 'No full 30-minute learning block fits the available budget and topic estimates. Score gaps remain, but no tasks were added.';
  else summary = `Start with ${priorities[0].topic_name}. The plan includes ${priorities.length} remedial task${priorities.length === 1 ? '' : 's'} totalling ${plan.total_planned_minutes} of ${format(plan.available_minutes)} available minutes, ordered by score gap, configured importance and estimated study time.`;
  if (plan.topic_analysis.some((topic) => topic.observed_score === null)) summary += ' Missing scores were not treated as zero; the overall assessment result is unavailable.';
  if (priorities.some((task) => task.is_partial)) summary += ' At least one task is partial practice.';
  summary += ' Configured weights and study times are planning assumptions. This plan does not predict or guarantee an exam score.';
  return { summary, priorities, explanation_mode: 'template' };
}

module.exports = { explainPlan };
},
"engine/generate-plan.js": function(module, exports, require) {
'use strict';

const BLOCK_MINUTES = 30;

function taskId(studentId, courseId, topicId, taskType = 'remedial') {
  return ['studygps', taskType, studentId, courseId, topicId].map(encodeURIComponent).join(':');
}

function allocateTasks(input, course, rankedTopics) {
  const configured = new Map(course.topics.map((topic) => [topic.topic_id, topic]));
  const priorities = [];
  const warnings = [];
  let remaining = input.available_minutes;
  for (const topic of rankedTopics) {
    if (remaining < BLOCK_MINUTES) break;
    const duration = Math.floor(Math.min(remaining, topic.estimated_minutes) / BLOCK_MINUTES) * BLOCK_MINUTES;
    if (duration === 0) {
      warnings.push({ code: 'TOPIC_BELOW_BLOCK_SIZE', topic_id: topic.topic_id, message: `${topic.topic_name} has a configured estimate below 30 minutes, so no full learning block fits.` });
      continue;
    }
    const resource = configured.get(topic.topic_id);
    priorities.push({
      task_id: taskId(input.student_id, input.course_id, topic.topic_id),
      task_type: 'remedial',
      topic_id: topic.topic_id,
      topic_name: topic.topic_name,
      priority: priorities.length + 1,
      duration_minutes: duration,
      estimated_minutes: topic.estimated_minutes,
      is_partial: duration < topic.estimated_minutes,
      resource_id: resource.resource_id,
      resource_ref: resource.resource_ref,
      activity: resource.activity,
      reason: '',
    });
    remaining -= duration;
  }
  return { priorities, warnings };
}

module.exports = { allocateTasks, taskId, BLOCK_MINUTES };
},
"engine/index.js": function(module, exports, require) {
'use strict';

const { validateInput, StudyPlanValidationError } = require('./validate-input');
const { analysePerformance, rankTopics } = require('./analyse-performance');
const { allocateTasks } = require('./generate-plan');
const { comparePlans } = require('./compare-plans');
const { explainPlan } = require('./explain-plan');

function generateStudyPlan(input, course, previousPlan = null) {
  validateInput(input, course);
  const analysis = analysePerformance(input, course);
  const ranked = rankTopics(analysis.topic_analysis);
  const allocated = allocateTasks(input, course, ranked);
  const total = allocated.priorities.reduce((sum, task) => sum + task.duration_minutes, 0);
  let status = 'ready';
  if (analysis.topic_analysis.every((topic) => topic.observed_score === null)) status = 'no_scores';
  else if (ranked.length === 0) status = 'target_met';
  else if (input.available_minutes === 0) status = 'no_study_time';
  else if (allocated.priorities.length === 0) status = 'insufficient_block_time';
  const calculated = {
    schema_version: '1.0',
    student_id: input.student_id,
    course_id: input.course_id,
    assessment_id: input.assessment_id,
    exam_date: input.exam_date ?? null,
    status,
    overall_score: analysis.overall_score,
    overall_score_basis: 'configured_importance_weighted_assessment',
    target_score: input.target_score,
    available_minutes: input.available_minutes,
    total_planned_minutes: total,
    unused_minutes: input.available_minutes - total,
    topic_analysis: analysis.topic_analysis,
    priorities: allocated.priorities,
    warnings: [...analysis.warnings, ...allocated.warnings],
  };
  const plan = { ...calculated, ...explainPlan(calculated) };
  return { ...plan, ...comparePlans(previousPlan, plan) };
}

module.exports = { generateStudyPlan, comparePlans, explainPlan, StudyPlanValidationError };
},
