'use strict';

class StudyPlanValidationError extends Error {
  constructor(issues) {
    super(`Study plan validation failed: ${issues.map(({ path, message }) => `${path}: ${message}`).join('; ')}`);
    this.name = 'StudyPlanValidationError';
    this.code = 'VALIDATION_ERROR';
    this.issues = issues;
  }
}

